# Read-only: the newest audit entries, Defender state, and Desktop MCP logs.
$a = Join-Path $env:USERPROFILE '.agentshield\audit.jsonl'
Get-Content $a | Select-Object -Last 25 | ForEach-Object {
  $e = $_ | ConvertFrom-Json
  $rule = ($e.triggered_rules -join ',')
  $orig = if ($e.original_decision) { " (would be $($e.original_decision))" } else { '' }
  $what = if ($e.tool_name) { $e.tool_name } else { '' }
  $cmd = "$($e.command)"
  if ($cmd.Length -gt 90) { $cmd = $cmd.Substring(0, 90) }
  "{0} {1,-20} {2,-6}{3} {4} [{5}] {6}" -f $e.timestamp.Substring(11, 8), $e.source, $e.decision, $orig, $what, $rule, $cmd
}
"--- defender"
Get-MpComputerStatus | Select-Object RealTimeProtectionEnabled, BehaviorMonitorEnabled, OnAccessProtectionEnabled, IoavProtectionEnabled | Format-List | Out-String -Width 200
$p = Get-MpPreference
"MAPSReporting=" + $p.MAPSReporting + " SubmitSamplesConsent=" + $p.SubmitSamplesConsent + " exclusions=" + ($p.ExclusionPath -join ',')
