param([Parameter(Mandatory)][string]$Script, [string]$Pin = '')
# Run install.ps1 the way `irm | iex` does, in a throwaway profile, against
# the LAN test server. The installer adds its folder to the user PATH, so the
# real user PATH is saved first and put back afterwards.
$saved = [Environment]::GetEnvironmentVariable('Path', 'User')
$sb = Join-Path $env:TEMP ('pin-test-' + [Guid]::NewGuid().ToString('N').Substring(0, 8))
New-Item -ItemType Directory -Force (Join-Path $sb 'AppData\Local'), (Join-Path $sb 'AppData\Roaming') | Out-Null
try {
    $env:USERPROFILE = $sb
    $env:HOME = $sb
    $env:LOCALAPPDATA = Join-Path $sb 'AppData\Local'
    $env:APPDATA = Join-Path $sb 'AppData\Roaming'
    $env:AGENTSHIELD_RELEASE_BASE = 'http://192.0.2.10:8765'
    if ($Pin) { $env:AGENTSHIELD_VERSION = $Pin } else { Remove-Item Env:AGENTSHIELD_VERSION -ErrorAction SilentlyContinue }
    try {
        Get-Content $Script -Raw | Invoke-Expression
    } catch {
        "INSTALL THREW: " + $_.Exception.Message
    }
    $exe = Join-Path $env:LOCALAPPDATA 'Programs\AgentShield\agentshield.exe'
    if (Test-Path $exe) { "installed: " + (& $exe version 2>&1 | Select-Object -First 1) } else { "installed: none" }
} finally {
    [Environment]::SetEnvironmentVariable('Path', $saved, 'User')
    "user PATH restored: " + ([Environment]::GetEnvironmentVariable('Path', 'User') -eq $saved)
}

# Pre-install risk tests for the CEO laptop (#4717), on the box's installed
# v0.2.2619. No new copy of agentshield.exe is written anywhere (a junction is
# used for the odd-path test), so Defender sees nothing new.
#   -Only A  heartbeat comes back after it dies (reboot stand-in)
#   -Only B  hook latency, Defender on
#   -Only C  hook path and home with spaces + non-ASCII
#   -Only D  existing settings.json with BOM, CRLF and other tools' hooks
#   -Only E  Claude Code with no Git Bash on PATH
#   -Only F  installer under Constrained Language Mode (locked-down laptop)
