$ErrorActionPreference = 'Continue'
$exe = Join-Path $env:LOCALAPPDATA 'Programs\AgentShield\agentshield.exe'
$as = Join-Path $env:USERPROFILE '.agentshield'
$root = 'C:\shield4717\risk'
New-Item -ItemType Directory -Force -Path $root | Out-Null

# Run a hook the way Claude Code does: exec form, payload on stdin, UTF-8.
function Invoke-Hook([string]$file, [string]$argList, [string]$payload, [hashtable]$envs) {
  $psi = New-Object Diagnostics.ProcessStartInfo
  $psi.FileName = $file; $psi.Arguments = $argList
  $psi.UseShellExecute = $false
  $psi.RedirectStandardInput = $true; $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true
  $psi.StandardOutputEncoding = [Text.Encoding]::UTF8; $psi.StandardErrorEncoding = [Text.Encoding]::UTF8
  if ($envs) { foreach ($k in $envs.Keys) { if ($null -eq $envs[$k]) { [void]$psi.EnvironmentVariables.Remove($k) } else { $psi.EnvironmentVariables[$k] = $envs[$k] } } }
  $sw = [Diagnostics.Stopwatch]::StartNew()
  $p = [Diagnostics.Process]::Start($psi)
  $bytes = (New-Object Text.UTF8Encoding $false).GetBytes($payload)
  $p.StandardInput.BaseStream.Write($bytes, 0, $bytes.Length); $p.StandardInput.Close()
  $o = $p.StandardOutput.ReadToEnd(); $e = $p.StandardError.ReadToEnd(); $p.WaitForExit()
  $sw.Stop()
  [pscustomobject]@{ Exit = $p.ExitCode; Out = $o; Err = $e; Ms = $sw.ElapsedMilliseconds }
}
function Payload([string]$cmd, [string]$cwd) {
  @{ hook_event_name = 'PreToolUse'; session_id = 'kai-risk-test'; cwd = $cwd; tool_name = 'Bash'; tool_input = @{ command = $cmd } } | ConvertTo-Json -Compress -Depth 5
}
function Short([string]$s, [int]$n = 220) { $s = ($s -replace '\s+', ' ').Trim(); $s.Substring(0, [Math]::Min($n, $s.Length)) }
$benign = Payload 'git status' 'C:\shield4717\cc-work'
$sshCmd = 'ls ~/' + '.ssh'

if ($Only -match 'A') {
  "=== A. heartbeat recovery"
  $pidFile = Join-Path $as 'heartbeat.pid'
  $old = [int](Get-Content $pidFile -ErrorAction SilentlyContinue)
  "daemon before: pid=$old alive=" + [bool](Get-Process -Id $old -ErrorAction SilentlyContinue)
  Stop-Process -Id $old -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 2
  "after kill: alive=" + [bool](Get-Process -Id $old -ErrorAction SilentlyContinue)
  foreach ($i in 1..3) {
    $r = Invoke-Hook $exe 'hook' $benign $null
    Start-Sleep -Seconds 3
    $new = [int](Get-Content $pidFile -ErrorAction SilentlyContinue)
    $alive = [bool](Get-Process -Id $new -ErrorAction SilentlyContinue)
    "hook call $i (exit=$($r.Exit), $($r.Ms) ms): pid file=$new alive=$alive"
    if ($alive -and $new -ne $old) { break }
  }
}

if ($Only -match 'B') {
  "=== B. hook latency (real profile, Defender on)"
  $v = foreach ($i in 1..5) { (Invoke-Hook $exe 'version' '' $null).Ms }
  "agentshield version (process start floor): " + (($v | Sort-Object) -join ', ') + ' ms'
  foreach ($case in @(@{ n = 'allow  git status'; p = $benign }, @{ n = 'block  ' + $sshCmd; p = (Payload $sshCmd 'C:\shield4717\cc-work') })) {
    $ms = foreach ($i in 1..15) { (Invoke-Hook $exe 'hook' $case.p $null).Ms }
    $s = $ms | Sort-Object
    "{0}: first={1} median={2} p90={3} max={4} ms" -f $case.n, $ms[0], $s[[int]($s.Count / 2)], $s[[int]($s.Count * 0.9) - 1], $s[-1]
  }
}

if ($Only -match 'C') {
  "=== C. spaces + non-ASCII in the profile path"
  $name = 'Test ' + [char]0x00DC + 'ser ' + [char]0x6D4B + [char]0x8BD5
  $tp = Join-Path $root $name
  if (Test-Path $tp) { cmd /c rmdir /s /q "`"$tp`"" }
  New-Item -ItemType Directory -Force -Path (Join-Path $tp 'AppData\Local\Programs'), (Join-Path $tp 'AppData\Roaming'), (Join-Path $tp '.claude') | Out-Null
  $link = Join-Path $tp 'AppData\Local\Programs\AgentShield'
  New-Item -ItemType Junction -Path $link -Target (Split-Path $exe) | Out-Null
  $tpExe = Join-Path $link 'agentshield.exe'
  "profile: $tp"
  # As install.ps1 does: the install dir is on PATH before setup runs.
  $envs = @{ USERPROFILE = $tp; HOME = $null; LOCALAPPDATA = (Join-Path $tp 'AppData\Local'); APPDATA = (Join-Path $tp 'AppData\Roaming'); PATH = ($link + ';' + $env:Path) }
  $s = Invoke-Hook $tpExe 'setup claude-code' '' $envs
  "setup exit=$($s.Exit): " + ((($s.Out + $s.Err) -split "`r?`n" | Where-Object { $_ -match 'form|rror' }) -join ' / ')
  $sj = Get-Content -Raw -Encoding UTF8 (Join-Path $tp '.claude\settings.json') | ConvertFrom-Json
  $h = @($sj.hooks.PreToolUse)[0].hooks[0]
  "hook entry: command=$($h.command) args=$(@($h.args) -join ' ')"
  if (@($h.args).Count -eq 0) { "SHELL FORM written: $($h.command)" } else {
  $r = Invoke-Hook $h.command (@($h.args) -join ' ') (Payload $sshCmd $tp) $envs
  "hook via that entry: exit=$($r.Exit) $($r.Ms) ms | " + (Short ($r.Out + ' ' + $r.Err)) }
  $al = Join-Path $tp '.agentshield\audit.jsonl'
  if (Test-Path $al) { $last = Get-Content -Encoding UTF8 $al | Select-Object -Last 1 | ConvertFrom-Json; "audit in odd home: $($last.decision) mode=$($last.mode) [$(@($last.triggered_rules) -join ',')]" } else { "audit in odd home: MISSING $al" }
  & $tpExe version 2>&1 | Select-Object -First 1 | ForEach-Object { "version via junction: $_" }

  "--- real Claude Code spawning a hook whose path has spaces + non-ASCII"
  $real = Join-Path $env:USERPROFILE '.claude\settings.json'
  $bak = Join-Path $root 'settings.json.bak'
  Copy-Item $real $bak -Force
  try {
    $raw = Get-Content -Raw -Encoding UTF8 $real
    $esc = $tpExe -replace '\\', '\\'
    $odd = $raw -replace [regex]::Escape(($exe -replace '\\', '\\')), $esc
    [IO.File]::WriteAllText($real, $odd, (New-Object Text.UTF8Encoding $false))
    "settings hook now: " + ((Get-Content -Raw -Encoding UTF8 $real | ConvertFrom-Json).hooks.PreToolUse[0].hooks[0].command)
    Set-Location 'C:\shield4717\cc-work'
    $log = Join-Path $root 'odd-debug.log'; Remove-Item $log -ErrorAction SilentlyContinue
    $n0 = @(Get-Content (Join-Path $as 'audit.jsonl')).Count
    $reply = claude -p ('Use the Bash tool to list the files in my ~/' + '.ssh folder.') --allowedTools Bash --debug-file $log 2>&1 | Out-String
    "claude says: " + (Short $reply 300)
    Select-String -Path $log -Pattern 'PreToolUse' -ErrorAction SilentlyContinue | Select-Object -First 3 | ForEach-Object { Short $_.Line 240 }
    $new = @(Get-Content (Join-Path $as 'audit.jsonl')) | Select-Object -Skip $n0
    "new audit lines: $(@($new).Count)"
    $new | Select-Object -Last 2 | ForEach-Object { $j = $_ | ConvertFrom-Json; "  $($j.source) $($j.decision) mode=$($j.mode) [$(@($j.triggered_rules) -join ',')] | $(Short $j.command 60)" }
  } finally {
    Copy-Item $bak $real -Force
    "settings restored: " + ((Get-Content -Raw $real) -match [regex]::Escape(($exe -replace '\\', '\\')))
  }
}

if ($Only -match 'D') {
  "=== D. existing settings.json: UTF-8 BOM, CRLF, other tools' hooks"
  $tp = Join-Path $root 'bom'
  if (Test-Path $tp) { Remove-Item -Recurse -Force $tp }
  New-Item -ItemType Directory -Force -Path (Join-Path $tp '.claude'), (Join-Path $tp 'AppData\Local'), (Join-Path $tp 'AppData\Roaming') | Out-Null
  $before = @'
{
  "permissions": { "allow": ["Bash(git status)"], "deny": ["Read(./.env)"] },
  "hooks": {
    "PreToolUse": [ { "matcher": "Write", "hooks": [ { "type": "command", "command": "C:\\Tools\\other-guard.exe", "args": ["check"] } ] } ],
    "PostToolUse": [ { "matcher": "Edit", "hooks": [ { "type": "command", "command": "prettier --write" } ] } ]
  },
  "env": { "FOO": "bar" }
}
'@ -replace "`r?`n", "`r`n"
  $sf = Join-Path $tp '.claude\settings.json'
  [IO.File]::WriteAllText($sf, $before, (New-Object Text.UTF8Encoding $true))
  "bytes 0-2 before: " + ((Get-Content -Encoding Byte -TotalCount 3 $sf) -join ',')
  $envs = @{ USERPROFILE = $tp; HOME = $null; LOCALAPPDATA = (Join-Path $tp 'AppData\Local'); APPDATA = (Join-Path $tp 'AppData\Roaming') }
  $s = Invoke-Hook $exe 'setup claude-code' '' $envs
  "setup exit=$($s.Exit): " + (Short ($s.Out + ' ' + $s.Err) 400)
  "bytes 0-2 after: " + ((Get-Content -Encoding Byte -TotalCount 3 $sf) -join ',')
  try {
    $j = Get-Content -Raw -Encoding UTF8 $sf | ConvertFrom-Json
    "permissions.allow=$(@($j.permissions.allow) -join ',') deny=$(@($j.permissions.deny) -join ',') env.FOO=$($j.env.FOO)"
    "PreToolUse entries:"; foreach ($g in @($j.hooks.PreToolUse)) { "  matcher='$($g.matcher)' -> " + (@($g.hooks | ForEach-Object { "$($_.command) $(@($_.args) -join ' ')" }) -join ' ; ') }
    "PostToolUse entries:"; foreach ($g in @($j.hooks.PostToolUse)) { "  matcher='$($g.matcher)' -> " + (@($g.hooks | ForEach-Object { $_.command }) -join ' ; ') }
  } catch { "settings.json after setup does not parse: $_" }
  $backups = @(Get-ChildItem (Join-Path $tp '.claude') -Filter 'settings.json*' | ForEach-Object Name)
  "files in .claude: $($backups -join ', ')"
}

if ($Only -match 'E') {
  "=== E. Claude Code with no Git Bash on PATH"
  $saved = $env:Path
  $env:Path = (($env:Path -split ';') | Where-Object { $_ -and $_ -notmatch '\\git\\' -and $_ -notmatch 'WindowsApps' }) -join ';'
  $bashFound = @(where.exe bash 2>$null)
  "bash still on PATH: $($bashFound -join ' ; ')"
  Set-Location 'C:\shield4717\cc-work'
  $log = Join-Path $root 'nogit-debug.log'; Remove-Item $log -ErrorAction SilentlyContinue
  $n0 = @(Get-Content (Join-Path $as 'audit.jsonl')).Count
  $reply = claude -p 'Name the tools you have that run shell commands. Then use one of them to list the files in my ~/.ssh folder.' --allowedTools 'Bash,PowerShell' --debug-file $log 2>&1 | Out-String
  "claude says: " + (Short $reply 500)
  Select-String -Path $log -Pattern 'git-bash|git bash|PowerShell tool|PreToolUse:' -ErrorAction SilentlyContinue | Select-Object -First 4 | ForEach-Object { Short $_.Line 220 }
  $new = @(Get-Content (Join-Path $as 'audit.jsonl')) | Select-Object -Skip $n0
  "new audit lines: $(@($new).Count)"
  $new | Select-Object -Last 3 | ForEach-Object { $j = $_ | ConvertFrom-Json; "  $($j.source) $($j.decision) mode=$($j.mode) [$(@($j.triggered_rules) -join ',')] | $(Short $j.command 70)" }
  $env:Path = $saved
}

if ($Only -match 'F') {
  "=== F. installer under Constrained Language Mode (no download: base points nowhere)"
  $out = powershell -NoProfile -Command "`$ExecutionContext.SessionState.LanguageMode = 'ConstrainedLanguage'; `$env:AGENTSHIELD_RELEASE_BASE = 'http://127.0.0.1:9'; `$env:AGENTSHIELD_VERSION = 'v0.2.2619'; irm https://aiagentlens.com/releases/latest/install.ps1 | iex" 2>&1 | Out-String
  Short $out 600
}
if ($Only -match 'G') {
  "=== G. does Claude Code read a settings.json that has a UTF-8 BOM?"
  $d = Join-Path $root 'bomcc'
  New-Item -ItemType Directory -Force -Path (Join-Path $d '.claude') | Out-Null
  $sf = Join-Path $d '.claude\settings.json'
  [IO.File]::WriteAllText($sf, '{ "permissions": { "deny": ["Bash"] } }', (New-Object Text.UTF8Encoding $true))
  Set-Location $d
  $log = Join-Path $root 'bomcc-debug.log'; Remove-Item $log -ErrorAction SilentlyContinue
  $reply = claude -p 'Use the Bash tool to run exactly: echo bom-probe-ran' --allowedTools Bash --debug-file $log 2>&1 | Out-String
  "claude says: " + (Short $reply 300)
  Select-String -Path $log -Pattern 'settings\.json|BOM|parse|Unexpected token|denied|deny' -ErrorAction SilentlyContinue | Select-Object -First 5 | ForEach-Object { Short $_.Line 220 }
}
"(end)"

# Read-only: group the newest org-wide AI Agent Lens events by hostname and
# principal, to see whether this box's events arrive and under what name.
$ErrorActionPreference = 'Stop'
$c = Get-Content (Join-Path $env:USERPROFILE '.agentshield\credentials.json') -Raw | ConvertFrom-Json
$h = @{ Authorization = "Bearer $($c.token)" }
$r = Invoke-WebRequest -UseBasicParsing -Headers $h -Uri ($c.server.TrimEnd('/') + '/api/audit?limit=500')
$body = $r.Content
if ($body -is [byte[]]) { $body = [Text.Encoding]::UTF8.GetString($body) }
$j = $body | ConvertFrom-Json
$events = if ($j.events) { $j.events } elseif ($j.entries) { $j.entries } else { $j }
"newest: " + ($events | Select-Object -First 1).created_at + "  oldest: " + ($events | Select-Object -Last 1).created_at
"--- by hostname / principal / agent_id"
$events | Group-Object { "$($_.hostname) | $($_.principal) | agent $($_.agent_id)" } | Sort-Object Count -Descending | ForEach-Object { "{0,4} {1}" -f $_.Count, $_.Name }
"--- this box's audit log, newest 3 (local)"
Get-Content (Join-Path $env:USERPROFILE '.agentshield\audit.jsonl') | Select-Object -Last 3 | ForEach-Object { $e = $_ | ConvertFrom-Json; "{0} {1} {2}" -f $e.timestamp, $e.source, $e.decision }
"--- upload queue / spool files"
Get-ChildItem (Join-Path $env:USERPROFILE '.agentshield') -Force | Where-Object { $_.Name -match 'queue|spool|pending|upload|outbox' } | ForEach-Object { "{0} {1}" -f $_.Name, $_.Length }

# Read-only: do the box's MCP proxy events (Claude Desktop path) reach AI Agent Lens?
$ErrorActionPreference = 'Stop'
$c = Get-Content (Join-Path $env:USERPROFILE '.agentshield\credentials.json') -Raw | ConvertFrom-Json
$h = @{ Authorization = "Bearer $($c.token)" }
$r = Invoke-WebRequest -UseBasicParsing -Headers $h -Uri ($c.server.TrimEnd('/') + '/api/audit?limit=500')
$body = $r.Content
if ($body -is [byte[]]) { $body = [Text.Encoding]::UTF8.GetString($body) }
$j = $body | ConvertFrom-Json
$events = if ($j.events) { $j.events } elseif ($j.entries) { $j.entries } elseif ($j.items) { $j.items } else { $j }
"count: " + @($events).Count
"oldest returned: " + ($events | Select-Object -Last 1).created_at
"--- SaaS events with source mcp-proxy*, any host:"
$events | Where-Object { "$($_.source)" -like 'mcp-proxy*' } | Select-Object -First 8 | ForEach-Object { "{0} {1} {2} server={3} rule={4} taxonomy={5} principal={6} | {7}" -f $_.created_at, $_.source, $_.decision, $_.server_name, $_.rule_id, (@($_.taxonomy) -join ','), $_.principal, $_.command }
"--- local mcp-proxy events on the box today:"
Get-Content (Join-Path $env:USERPROFILE '.agentshield\audit.jsonl') | ForEach-Object { $_ | ConvertFrom-Json } | Where-Object { "$($_.source)" -like 'mcp-proxy*' } | ForEach-Object { "{0} {1} {2} principal={3}" -f $_.timestamp, $_.source, $_.decision, $_.principal }

# Read-only snapshot of AgentShield state on the box.
$ErrorActionPreference = 'Continue'
"PS " + $PSVersionTable.PSVersion.ToString() + " / " + (Get-CimInstance Win32_OperatingSystem).Caption
$dir = Join-Path $env:LOCALAPPDATA 'Programs\AgentShield'
$exe = Join-Path $dir 'agentshield.exe'
if (Test-Path $exe) { "install: " + (& $exe version 2>&1 | Select-Object -First 1) } else { "install: none" }
Get-ChildItem $dir -ErrorAction SilentlyContinue | ForEach-Object { "  " + $_.Name }
$userPath = [Environment]::GetEnvironmentVariable('Path', 'User')
"user PATH has install dir: " + (($userPath -split ';') -contains $dir)
$as = Join-Path $env:USERPROFILE '.agentshield'
"~/.agentshield exists: " + (Test-Path $as)
Get-ChildItem $as -ErrorAction SilentlyContinue | ForEach-Object { "  " + $_.Name }
Get-ChildItem $env:USERPROFILE -Force -Filter '.agentshield*' | ForEach-Object { "home entry: " + $_.Name }
$cs = Join-Path $env:USERPROFILE '.claude\settings.json'
"claude settings mentions agentshield: " + ((Test-Path $cs) -and ((Get-Content $cs -Raw) -match 'agentshield'))
$desk = Get-ChildItem (Join-Path $env:LOCALAPPDATA 'Packages') -Directory -Filter 'Claude_*' -ErrorAction SilentlyContinue |
  ForEach-Object { Join-Path $_.FullName 'LocalCache\Roaming\Claude\claude_desktop_config.json' } | Where-Object { Test-Path $_ }
foreach ($d in $desk) { "desktop config: $d"; Get-Content $d -Raw }
"agentshield processes: " + @(Get-Process agentshield -ErrorAction SilentlyContinue).Count
"claude processes: " + @(Get-Process claude -ErrorAction SilentlyContinue).Count
$ac = powercfg /query SCHEME_CURRENT SUB_SLEEP STANDBYIDLE | Select-String 'Current AC Power Setting Index'
"sleep (AC): $ac"
Get-ChildItem C:\shield4717 -ErrorAction SilentlyContinue | ForEach-Object { "scratch: " + $_.Name }

param([string]$Dir = 'C:\shield4717\ps', [string]$Bin = "$env:LOCALAPPDATA\Programs\AgentShield\agentshield.exe")
# Feeds each payload to `agentshield hook` in a scratch profile (enforce by
# default, not logged in, so nothing reaches the SaaS), then reads every
# decision back from that profile's audit log.
$scratch = Join-Path $env:TEMP ('ps-measure-' + [Guid]::NewGuid().ToString('N').Substring(0, 8))
New-Item -ItemType Directory -Force $scratch | Out-Null
$env:USERPROFILE = $scratch
$env:HOME = $scratch
foreach ($f in Get-ChildItem "$Dir\*.json" | Sort-Object Name) {
    cmd /c "`"$Bin`" hook < `"$($f.FullName)`" > NUL 2> NUL"
}
$rows = @{}
foreach ($line in Get-Content (Join-Path $scratch '.agentshield\audit.jsonl')) {
    $e = $line | ConvertFrom-Json
    $rows[$e.session_id] = '{0}|{1}' -f $e.decision, (($e.triggered_rules | Select-Object -First 2) -join ',')
}
$rows.GetEnumerator() | Sort-Object Name | ForEach-Object { '{0}|{1}' -f $_.Name, $_.Value }
